```csharp
using System;

class MainClass {
  public static void Main (string[] args) {
    int n = 10; // number of tasks
    int r = 3; // number of deviations
    int totalCombinations = CalculateCombinations(n, r);
    Console.WriteLine("Total possible combinations for Alice's morning routine: " + totalCombinations);
  }

  public static int CalculateCombinations(int n, int r) {
    return Factorial(n) / (Factorial(r) * Factorial(n - r));
  }

  public static int Factorial(int number) {
    if (number == 0 || number == 1) {
      return 1;
    } else {
      return number * Factorial(number - 1);
    }
  }
}
