In C++, you can create a linked list by defining a structure for the nodes and implementing functions for common operations like insertion and traversal. Here's an example of how to create a simple singly linked list:

1. First define a `Node` structure, which contains a data element and a pointer to the next node.

```cpp
#include <iostream>

struct Node {
    int data;
    Node* next;
};
```

2. Next, create functions to perform common operations on the linked list, such as inserting a new node (`insert`) and displaying the list (`display`).

```cpp
// Insert a new node at the end of the list
Node* insert(Node* head, int data) {
    // Create a new node
    Node* newNode = new Node();
    newNode->data = data;
    newNode->next = nullptr;

    // If the list is empty, the new node becomes the head
    if (head == nullptr) {
        head = newNode;
    } else {
        // Traverse to the end of the list and add the new node
        Node* current = head;
        while (current->next != nullptr) {
            current = current->next;
        }
        current->next = newNode;
    }

    return head;
}

// Display the linked list
void display(Node* head) {
    Node* current = head;
    while (current != nullptr) {
        std::cout << current->data << " -> ";
        current = current->next;
    }
    std::cout << "NULL" << std::endl;
}
```

3. Finally, use these functions to create and manipulate a linked list in the `main` function.

```cpp
int main() {
    Node* head = nullptr;

    // Insert data into the linked list
    head = insert(head, 1);
    head = insert(head, 2);
    head = insert(head, 3);
    head = insert(head, 4);
    head = insert(head, 5);

    // Display the linked list
    display(head);

    return 0;
}
```

This example will create a singly linked list with elements 1, 2, 3, 4, and 5, and display it as: `1 -> 2 -> 3 -> 4 -> 5 -> NULL`.

